typedef long long ll;

static ll llabsll(ll x) { return x < 0 ? -x : x; }

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    ll *a = (ll*)malloc((n + 1) * sizeof(ll)); /* coefficients: a[n]x^n + ... + a[0] */
    for (int i = n; i >= 0; --i) {
        if (scanf("%lld", &a[i]) != 1) return 0;
    }

    /* Repeatedly find an integer root using Rational Root Theorem,
       then synthetic divide. Assumes the polynomial factors completely
       into linear factors over integers. */
    ll *roots = (ll*)malloc(n * sizeof(ll));
    int rcnt = 0;
    int deg = n;

    while (deg > 0) {
        ll c = a[0];
        ll root = 0;
        int found = 0;

        if (c == 0) {
            root = 0;
            found = 1;
        } else {
            ll ac = llabsll(c);
            for (ll d = 1; d * d <= ac && !found; ++d) {
                if (ac % d) continue;

                ll cand[4];
                int m = 0;
                cand[m++] = d;
                cand[m++] = -d;
                if (d * d != ac) {
                    cand[m++] = ac / d;
                    cand[m++] = -(ac / d);
                }

                for (int k = 0; k < m && !found; ++k) {
                    ll r = cand[k];
                    __int128 val = 0;
                    for (int i = deg; i >= 0; --i) {
                        val = val * r + a[i];
                    }
                    if (val == 0) {
                        root = r;
                        found = 1;
                    }
                }
            }
        }

        if (!found) {
            /* If input guarantees factorization into linear integer factors,
               this should never happen. */
            free(a);
            free(roots);
            return 0;
        }

        roots[rcnt++] = root;

        /* Synthetic division by (x - root):
           b[deg-1] = a[deg]
           b[i] = a[i+1] + root * b[i+1] for i = deg-2..0
        */
        ll *b = (ll*)malloc(deg * sizeof(ll));
        b[deg - 1] = a[deg];
        for (int i = deg - 2; i >= 0; --i) {
            __int128 t = (__int128)a[i + 1] + (__int128)root * b[i + 1];
            b[i] = (ll)t;
        }

        free(a);
        a = b;
        deg--;
    }

    /* Output as product of linear factors. */
    for (int i = 0; i < rcnt; ++i) {
        ll r = roots[i];
        if (r == 0) {
            printf("(x)");
        } else if (r > 0) {
            printf("(x-%lld)", r);
        } else {
            printf("(x+%lld)", -r);
        }
    }
    printf("\n");

    free(a);
    free(roots);
    return 0;
}

