// Perform synthetic division by (x - root), returns quotient coefficients
vector<int> syntheticDivision(const vector<int>& coeffs, int root) {
    int n = coeffs.size();
    vector<int> result(n - 1, 0);
    int carry = 0;
    for (int i = 0; i < n - 1; i++) {
        carry = coeffs[i] + carry * root;
        result[i] = carry;
    }
    // remainder = coeffs.back() + carry*root, should be 0
    return result;
}

