        } else {
            long long ac = llabs(c);
            for (long long d = 1; d * d <= ac; ++d) {
                if (ac % d == 0) {
                    candidates.push_back(d);
                    candidates.push_back(-d);
                    if (d * d != ac) {
                        candidates.push_back(ac / d);
                        candidates.push_back(-(ac / d));
                    }
                }
            }
        }

        bool found = false;
        long long root = 0;

        for (long long r : candidates) {
            if (eval(poly, r) == 0) {
                root = r;
                found = true;
                break;
