        Scanner sc = new Scanner(System.in);

        int n = sc.nextInt();
        int[] coeff = new int[n + 1];
        for (int i = 0; i <= n; i++) {
            coeff[i] = sc.nextInt();
        }

        int leading = coeff[0];
        int constant = coeff[n];

        List<Integer> roots = new ArrayList<>();
        // Try all divisors of constant / leading
        List<Integer> candidates = new ArrayList<>();
        int absConst = Math.abs(constant);
        int absLead = Math.abs(leading);

        for (int p = 1; p <= absConst; p++) {
            if (absConst % p == 0) {
                for (int q = 1; q <= absLead; q++) {
                    if (absLead % q == 0) {
                        int num = p;
                        int den = q;
                        // Reduce fraction (not necessary but okay)
                        candidates.add(num / gcd(num, den) * (den / gcd(num, den) > 0 ? 1 : -1));
                        // Actually simpler: just test p/q and -p/q
                    }
                }
            }
        }

        // Actually simpler approach: just test all divisors.
        List<Integer> divisors = new ArrayList<>();
        for (int i = 1; i <= absConst; i++) {
            if (absConst % i == 0) {
                divisors.add(i);
                divisors.add(-i);
            }
        }
        divisors.add(0);

        int[] poly = coeff.clone();
        for (int i = 0; i < n; i++) {
            // find one root
            int root = 0;
            for (int d : divisors) {
                if (eval(poly, d) == 0) {
                    root = d;
                    break;
                }
            }
            roots.add(root);
            poly = syntheticDivision(poly, root);
        }

        // Output factorization
        StringBuilder sb = new StringBuilder();
        if (leading != 1) {
            sb.append(leading);
        }
        for (int r : roots) {
            if (r == 0) {
                sb.append("x");
            } else if (r > 0) {
                sb.append("(x - ").append(r).append(")");
            } else {
                sb.append("(x + ").append(-r).append(")");
            }
        }
        System.out.println(sb.toString());

        sc.close();
    }

    static int eval(int[] poly, int x) {
        int result = 0;
        for (int c : poly) {
            result = result * x + c;
        }
        return result;
    }

    static int[] syntheticDivision(int[] poly, int root) {
        int n = poly.length;
        int[] result = new int[n - 1];
        int carry = 0;
        for (int i = 0; i < n - 1; i++) {
            carry = poly[i] + carry * root;
            result[i] = carry;
        }
        return result;
    }

    static int gcd(int a, int b) {
        return b == 0 ? a : gcd(b, a % b);
    }
}

