            long curLead = poly.get(0);

            Set<Long> pDivs = getDivisors(Math.abs(curConst));
            Set<Long> qDivs = getDivisors(Math.abs(curLead));

            outer:
            for (long p : pDivs) {
                for (long q : qDivs) {
                    // Try x = p/q and x = -p/q
                    // For integer roots only: q=1
                    for (int sign : new int[]{1, -1}) {
                        long r = sign * p; // integer root candidate
                        if (eval(poly, r) == 0) {
                            roots.add(r);
                            poly = divide(poly, r);
                            found = true;
                            break outer;
                        }
                    }
                }
            }
            if (!found) break;
        }

        StringBuilder sb = new StringBuilder();
        if (leading != 1) sb.append(leading);
        for (long r : roots) {
            if (r < 0) sb.append("(x+" + (-r) + ")");
            else if (r == 0) sb.append("(x)");
            else sb.append("(x-" + r + ")");
        }
        System.out.println(sb.toString());
    }

    static long eval(List<Long> poly, long x) {
        long val = 0;
        for (long c : poly) val = val * x + c;
        return val;
    }

    static List<Long> divide(List<Long> poly, long root) {
        List<Long> result = new ArrayList<>();
        long carry = 0;
        for (int i = 0; i < poly.size() - 1; i++) {
            carry = carry * root + poly.get(i);
            result.add(carry);
        }
        return result;
    }

    static Set<Long> getDivisors(long n) {
        Set<Long> divs = new TreeSet<>();
        if (n == 0) { divs.add(1L); return divs; }
        for (long i = 1; i * i <= n; i++) {
            if (n % i == 0) { divs.add(i); divs.add(n / i); }
        }
        return divs;
    }
}

