        return q;
    }

    static BigInteger eval(BigInteger[] coef, BigInteger x) {
        BigInteger res = BigInteger.ZERO;
        for (BigInteger c : coef) {
            res = res.multiply(x).add(c);
        }
        return res;
    }

    static List<BigInteger> divisors(BigInteger x) {
        x = x.abs();
        List<BigInteger> res = new ArrayList<>();
        if (x.equals(BigInteger.ZERO)) {
            res.add(BigInteger.ZERO);
            return res;
        }
        long v = x.longValueExact();
        for (long d = 1; d * d <= v; d++) {
            if (v % d == 0) {
                res.add(BigInteger.valueOf(d));
                if (d * d != v) res.add(BigInteger.valueOf(v / d));
            }
        }
        return res;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        String first = fs.next();
        if (first == null) return;
        int n = Integer.parseInt(first);

        BigInteger[] coef = new BigInteger[n + 1];
        for (int i = 0; i <= n; i++) coef[i] = new BigInteger(fs.next());

        List<BigInteger> roots = new ArrayList<>();

        while (coef.length > 1) {
            int deg = coef.length - 1;

            if (coef[deg].equals(BigInteger.ZERO)) {
                roots.add(BigInteger.ZERO);
                coef = Arrays.copyOf(coef, deg);
                continue;
            }

            BigInteger a0 = coef[0];
            BigInteger an = coef[deg];

            BigInteger found = null;

            List<BigInteger> pDivs = divisors(a0);
            List<BigInteger> qDivs = divisors(an);

            outer:
            for (BigInteger p : pDivs) {
                for (BigInteger q : qDivs) {
                    BigInteger[] cand = new BigInteger[]{
                            p.divide(p.gcd(q)),
                            q.divide(p.gcd(q))
                    };
                    BigInteger num = cand[0];
                    BigInteger den = cand[1];

                    if (den.equals(BigInteger.ONE)) {
                        BigInteger r1 = num;
                        if (eval(coef, r1).equals(BigInteger.ZERO)) {
                            found = r1;
                            break outer;
                        }
                        BigInteger r2 = num.negate();
                        if (eval(coef, r2).equals(BigInteger.ZERO)) {
                            found = r2;
                            break outer;
                        }
                    }
                }
            }

            if (found == null) break;

            roots.add(found);
            coef = divideByRoot(coef, found);
        }

        StringBuilder sb = new StringBuilder();
        if (coef.length == 1) {
            sb.append(coef[0].toString());
        } else {
            for (int i = 0; i < coef.length; i++) {
                if (i > 0) sb.append(' ');
                sb.append(coef[i].toString());
            }
        }
        sb.append('\n');

        for (BigInteger r : roots) {
            sb.append("(x");
            if (r.signum() < 0) sb.append('+').append(r.negate());
            else sb.append('-').append(r);
            sb.append(')');
        }
        sb.append('\n');

        System.out.print(sb.toString());
    }
}
